-- =============================================================================
-- Phase 10: Document Center (attachments on existing records)
--
-- Files live in the PRIVATE storage bucket `documents` under
--   <company_id>/<document_id>/v<version>-<random>.<ext>
-- The path is generated by the server; client file names are kept only as
-- metadata. Access needs documents.read (upload: documents.upload) AND the
-- read permission of the record the document is attached to, in the same
-- company. Objects can be created only for a pending version row of the
-- uploader, and are never updated or deleted through the API: a replacement
-- is a new version, and documents are archived, not deleted.
-- Server-side checks: extension allow-list, declared MIME type must match the
-- extension, size limit, object present with the declared size. File content
-- is not inspected on the server (the browser checks the file signature
-- before uploading).
-- =============================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('documents', 'documents', false, 26214400, array[
  'application/pdf', 'image/png', 'image/jpeg', 'image/webp', 'text/csv', 'text/plain',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document'])
on conflict (id) do nothing;

create table if not exists public.documents (
  id                  uuid primary key default gen_random_uuid(),
  company_id          uuid not null references public.companies (id) on delete restrict,
  document_type       text not null check (document_type in ('INVOICE_COPY', 'PURCHASE_ORDER', 'DELIVERY_PROOF', 'QUALITY_REPORT', 'CERTIFICATE',
                        'CONTRACT', 'KYC', 'SUPPLIER_DOCUMENT', 'DRAWING', 'PHOTO', 'OTHER')),
  title               text not null check (length(btrim(title)) between 1 and 200),
  description         text check (description is null or length(description) <= 1000),
  related_entity_type text not null check (related_entity_type in ('PRODUCT', 'BATCH', 'WAREHOUSE', 'PRODUCTION_ORDER', 'OUTSOURCING_ORDER',
                        'CUSTOMER_PO', 'SALES_ORDER', 'DISPATCH', 'INVOICE', 'ADJUSTMENT_NOTE', 'CUSTOMER', 'COMPANY')),
  related_entity_id   uuid not null,
  related_reference   text not null,
  status              text not null default 'ACTIVE' check (status in ('ACTIVE', 'ARCHIVED')),
  current_version     integer not null default 0,
  created_by          uuid,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  archived_by         uuid,
  archived_at         timestamptz,
  archive_reason      text check (archive_reason is null or length(archive_reason) <= 500),
  constraint documents_id_company_unique unique (id, company_id)
);

create index if not exists documents_entity_idx on public.documents (company_id, related_entity_type, related_entity_id);
create index if not exists documents_company_time_idx on public.documents (company_id, created_at desc);

create table if not exists public.document_versions (
  id                uuid primary key default gen_random_uuid(),
  company_id        uuid not null references public.companies (id) on delete restrict,
  document_id       uuid not null,
  version           integer not null check (version >= 1),
  original_filename text not null check (length(original_filename) between 1 and 200),
  storage_path      text not null unique,
  file_size         bigint not null check (file_size > 0),
  mime_type         text not null,
  extension         text not null,
  checksum_sha256   text check (checksum_sha256 is null or checksum_sha256 ~ '^[0-9a-f]{64}$'),
  change_note       text check (change_note is null or length(change_note) <= 500),
  status            text not null default 'PENDING_UPLOAD' check (status in ('PENDING_UPLOAD', 'AVAILABLE', 'FAILED')),
  uploaded_by       uuid not null,
  created_at        timestamptz not null default now(),
  uploaded_at       timestamptz,
  constraint document_versions_unique unique (document_id, version),
  constraint document_versions_doc_fk foreign key (document_id, company_id) references public.documents (id, company_id) on delete restrict
);

alter table public.documents enable row level security;
alter table public.document_versions enable row level security;
revoke all on public.documents, public.document_versions from anon, authenticated;
grant select on public.documents, public.document_versions to authenticated;

-- Record a document is attached to: existence in the company, reference, read permission, link.
create or replace function private.document_entity(p_company uuid, p_type text, p_id uuid)
returns table (reference text, read_permission text, link text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return query
  select x.reference, x.perm, x.link from (
    select p.sku as reference, 'products.read' as perm, '/products/' || p.id as link from public.products p where p_type = 'PRODUCT' and p.id = p_id and p.company_id = p_company
    union all select coalesce(b.batch_number, 'Untracked lot') || ' · ' || p.sku, 'inventory.read', '/inventory/stock/' || p.id
      from public.inventory_batches b join public.products p on p.id = b.product_id where p_type = 'BATCH' and b.id = p_id and b.company_id = p_company
    union all select w.warehouse_code, 'inventory.read', '/inventory/warehouses' from public.warehouses w where p_type = 'WAREHOUSE' and w.id = p_id and w.company_id = p_company
    union all select o.production_order_number, 'manufacturing.read', '/production/orders/' || o.id from public.production_orders o where p_type = 'PRODUCTION_ORDER' and o.id = p_id and o.company_id = p_company
    union all select o.outsourcing_order_number, 'outsourcing.read', '/production/outsourcing/' || o.id from public.outsourcing_orders o where p_type = 'OUTSOURCING_ORDER' and o.id = p_id and o.company_id = p_company
    union all select o.customer_po_number || ' (' || o.po_reference || ')', 'customer_po.read', '/customer-pos/' || o.id from public.customer_purchase_orders o where p_type = 'CUSTOMER_PO' and o.id = p_id and o.company_id = p_company
    union all select s.sales_order_number, 'sales_orders.read', '/sales/order-details?so=' || s.id from public.sales_orders s where p_type = 'SALES_ORDER' and s.id = p_id and s.company_id = p_company
    union all select f.fulfilment_number, 'fulfilment.read', '/sales/delivery?f=' || f.id from public.fulfilments f where p_type = 'DISPATCH' and f.id = p_id and f.company_id = p_company
    union all select coalesce(i.invoice_number, 'Draft invoice'), 'invoices.read', '/billing/invoices/' || i.id from public.sales_invoices i where p_type = 'INVOICE' and i.id = p_id and i.company_id = p_company
    union all select coalesce(n.note_number, 'Draft note'), 'invoices.read', '/billing/notes/' || n.id from public.invoice_adjustment_notes n where p_type = 'ADJUSTMENT_NOTE' and n.id = p_id and n.company_id = p_company
    union all select c.customer_code || ' — ' || c.customer_name, 'customers.read', '/customers' from public.customers c where p_type = 'CUSTOMER' and c.id = p_id and c.company_id = p_company
    union all select c.legal_name, 'settings.manage', '/settings' from public.companies c where p_type = 'COMPANY' and c.id = p_id and c.id = p_company
  ) x;
end;
$$;

create or replace function private.document_entity_permission(p_type text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case p_type when 'PRODUCT' then 'products.read' when 'BATCH' then 'inventory.read' when 'WAREHOUSE' then 'inventory.read'
    when 'PRODUCTION_ORDER' then 'manufacturing.read' when 'OUTSOURCING_ORDER' then 'outsourcing.read' when 'CUSTOMER_PO' then 'customer_po.read'
    when 'SALES_ORDER' then 'sales_orders.read' when 'DISPATCH' then 'fulfilment.read' when 'INVOICE' then 'invoices.read'
    when 'ADJUSTMENT_NOTE' then 'invoices.read' when 'CUSTOMER' then 'customers.read' when 'COMPANY' then 'settings.manage' end;
$$;

create or replace function private.document_readable(p_company uuid, p_entity_type text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_company = private.current_company_id()
     and private.has_permission(p_company, 'documents.read')
     and private.has_permission(p_company, private.document_entity_permission(p_entity_type));
$$;

revoke all on function private.document_entity(uuid, text, uuid) from public, anon, authenticated;
revoke all on function private.document_entity_permission(text) from public, anon, authenticated;
revoke all on function private.document_readable(uuid, text) from public, anon;
grant execute on function private.document_readable(uuid, text) to authenticated;

drop policy if exists documents_select on public.documents;
create policy documents_select on public.documents for select to authenticated
  using (private.document_readable(company_id, related_entity_type));
drop policy if exists document_versions_select on public.document_versions;
create policy document_versions_select on public.document_versions for select to authenticated
  using (exists (select 1 from public.documents d where d.id = document_id) and (status = 'AVAILABLE' or uploaded_by = auth.uid()));

-- Storage: read an object only if it is an available version of a document you can read.
create or replace function private.document_object_readable(p_name text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.document_versions v join public.documents d on d.id = v.document_id
    where v.storage_path = p_name and v.status = 'AVAILABLE' and private.document_readable(d.company_id, d.related_entity_type));
$$;

-- Storage: create an object only for your own pending version (prepared in the last hour).
create or replace function private.document_object_writable(p_name text)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.document_versions v
    where v.storage_path = p_name and v.status = 'PENDING_UPLOAD' and v.uploaded_by = auth.uid()
      and v.company_id = private.current_company_id() and v.created_at > now() - interval '1 hour'
      and private.has_permission(v.company_id, 'documents.upload'));
$$;

revoke all on function private.document_object_readable(text) from public, anon;
revoke all on function private.document_object_writable(text) from public, anon;
grant execute on function private.document_object_readable(text), private.document_object_writable(text) to authenticated;

drop policy if exists documents_objects_select on storage.objects;
create policy documents_objects_select on storage.objects for select to authenticated
  using (bucket_id = 'documents' and private.document_object_readable(name));
drop policy if exists documents_objects_insert on storage.objects;
create policy documents_objects_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'documents' and private.document_object_writable(name));
-- No update or delete policies: stored versions are immutable through the API.

-- Upload rules (company settings documents.max_file_mb / documents.allowed_extensions).
create or replace function private.document_rules(p_company uuid)
returns table (max_bytes bigint, extensions text[])
language sql
stable
security definer
set search_path = ''
as $$
  select least(coalesce((select (s.setting_value #>> '{}')::numeric from public.company_settings s
                         where s.company_id = p_company and s.setting_key = 'documents.max_file_mb' and jsonb_typeof(s.setting_value) = 'number'), 20), 25)::bigint * 1048576,
    coalesce((select array(select lower(jsonb_array_elements_text(s.setting_value)) intersect
                           select unnest(array['pdf', 'png', 'jpg', 'jpeg', 'webp', 'csv', 'txt', 'xlsx', 'docx']))
              from public.company_settings s where s.company_id = p_company and s.setting_key = 'documents.allowed_extensions' and jsonb_typeof(s.setting_value) = 'array'),
             array['pdf', 'png', 'jpg', 'jpeg', 'webp', 'csv', 'txt', 'xlsx', 'docx']);
$$;

create or replace function private.document_mime_for(p_ext text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case p_ext when 'pdf' then 'application/pdf' when 'png' then 'image/png' when 'jpg' then 'image/jpeg' when 'jpeg' then 'image/jpeg'
    when 'webp' then 'image/webp' when 'csv' then 'text/csv' when 'txt' then 'text/plain'
    when 'xlsx' then 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    when 'docx' then 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' end;
$$;

revoke all on function private.document_rules(uuid) from public, anon, authenticated;
revoke all on function private.document_mime_for(text) from public, anon, authenticated;

create or replace function public.document_upload_rules()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_company uuid := private.require_permission('documents.read');
  v_r record;
begin
  select * into v_r from private.document_rules(v_company);
  return jsonb_build_object('max_bytes', v_r.max_bytes, 'extensions', to_jsonb(v_r.extensions));
end;
$$;

-- Step 1: validate and reserve a server-generated path.
create or replace function public.document_upload_prepare(
  p_entity_type text, p_entity_id uuid, p_document_type text, p_title text, p_filename text, p_size bigint, p_mime text,
  p_description text default null, p_document_id uuid default null, p_change_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid := private.require_permission('documents.upload');
  v_entity  record;
  v_rules   record;
  v_name    text := regexp_replace(regexp_replace(coalesce(p_filename, ''), '^.*[\\/]', ''), '[[:cntrl:]]', '', 'g');
  v_ext     text;
  v_doc     public.documents;
  v_version int;
  v_path    text;
  v_vid     uuid;
begin
  v_name := left(btrim(v_name), 200);
  v_ext := lower(substring(v_name from '\.([A-Za-z0-9]{1,10})$'));
  select * into v_rules from private.document_rules(v_company);
  if v_name = '' or v_ext is null or not (v_ext = any (v_rules.extensions)) then
    raise exception 'File type not allowed. Allowed: %.', array_to_string(v_rules.extensions, ', ') using errcode = 'P0001';
  end if;
  if lower(coalesce(p_mime, '')) is distinct from private.document_mime_for(v_ext) then
    raise exception 'The file''s type (%) does not match its .% extension.', coalesce(nullif(p_mime, ''), 'unknown'), v_ext using errcode = 'P0001';
  end if;
  if p_size is null or p_size <= 0 or p_size > v_rules.max_bytes then
    raise exception 'Files must be between 1 byte and % MB.', v_rules.max_bytes / 1048576 using errcode = 'P0001';
  end if;

  if p_document_id is null then
    select * into v_entity from private.document_entity(v_company, p_entity_type, p_entity_id);
    if not found then
      raise exception 'The record to attach to was not found in your company.' using errcode = 'P0001';
    end if;
    if not private.has_permission(v_company, v_entity.read_permission) then
      raise exception 'You cannot attach documents to this record (requires %).', v_entity.read_permission using errcode = '42501';
    end if;
    begin
      insert into public.documents (company_id, document_type, title, description, related_entity_type, related_entity_id, related_reference, created_by)
      values (v_company, p_document_type, btrim(coalesce(nullif(p_title, ''), v_name)), nullif(btrim(coalesce(p_description, '')), ''),
        p_entity_type, p_entity_id, v_entity.reference, auth.uid())
      returning * into v_doc;
    exception when check_violation then
      raise exception 'Choose a supported document type and a title of up to 200 characters.' using errcode = 'P0001';
    end;
    v_version := 1;
  else
    select * into v_doc from public.documents where id = p_document_id and company_id = v_company for update;
    if not found or not private.document_readable(v_doc.company_id, v_doc.related_entity_type) then
      raise exception 'Document not found.' using errcode = 'P0001';
    end if;
    if v_doc.status <> 'ACTIVE' then
      raise exception 'Archived documents cannot receive new versions.' using errcode = 'P0001';
    end if;
    if length(btrim(coalesce(p_change_note, ''))) < 3 then
      raise exception 'Describe what changed in this revision.' using errcode = 'P0001';
    end if;
    v_version := (select coalesce(max(version), 0) + 1 from public.document_versions where document_id = v_doc.id);
  end if;
  if exists (select 1 from public.document_versions where document_id = v_doc.id and status = 'PENDING_UPLOAD' and created_at > now() - interval '1 hour') then
    raise exception 'Another upload for this document is in progress. Finish or cancel it first.' using errcode = 'P0001';
  end if;
  v_path := v_company || '/' || v_doc.id || '/v' || v_version || '-' || replace(gen_random_uuid()::text, '-', '') || '.' || v_ext;
  insert into public.document_versions (company_id, document_id, version, original_filename, storage_path, file_size, mime_type, extension, change_note, uploaded_by)
  values (v_company, v_doc.id, v_version, v_name, v_path, p_size, lower(p_mime), v_ext, nullif(btrim(coalesce(p_change_note, '')), ''), auth.uid())
  returning id into v_vid;
  return jsonb_build_object('document_id', v_doc.id, 'version_id', v_vid, 'version', v_version, 'bucket', 'documents', 'storage_path', v_path);
end;
$$;

-- Step 2: after the object was uploaded, verify it and publish the version.
create or replace function public.document_upload_complete(p_version_id uuid, p_checksum text default null)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid := private.require_permission('documents.upload');
  v_ver     public.document_versions;
  v_obj     record;
  v_doc     public.documents;
begin
  select * into v_ver from public.document_versions where id = p_version_id and company_id = v_company for update;
  if not found or v_ver.uploaded_by <> auth.uid() then
    raise exception 'Upload not found.' using errcode = 'P0001';
  end if;
  if v_ver.status <> 'PENDING_UPLOAD' then
    raise exception 'This upload is already %.', lower(v_ver.status) using errcode = 'P0001';
  end if;
  select o.metadata into v_obj from storage.objects o where o.bucket_id = 'documents' and o.name = v_ver.storage_path;
  if not found then
    raise exception 'The file has not been uploaded yet.' using errcode = 'P0001';
  end if;
  if (v_obj.metadata ->> 'size') is not null and (v_obj.metadata ->> 'size')::bigint <> v_ver.file_size then
    update public.document_versions set status = 'FAILED' where id = v_ver.id;
    raise exception 'The stored file size does not match the declared size; the upload was rejected.' using errcode = 'P0001';
  end if;
  if (v_obj.metadata ->> 'mimetype') is not null and lower(v_obj.metadata ->> 'mimetype') <> v_ver.mime_type then
    update public.document_versions set status = 'FAILED' where id = v_ver.id;
    raise exception 'The stored file type does not match the declared type; the upload was rejected.' using errcode = 'P0001';
  end if;
  update public.document_versions set status = 'AVAILABLE', uploaded_at = now(),
    checksum_sha256 = case when p_checksum ~ '^[0-9a-f]{64}$' then p_checksum end
  where id = v_ver.id;
  update public.documents set current_version = v_ver.version, updated_at = now() where id = v_ver.document_id returning * into v_doc;
  perform private.write_audit_log(v_company, case when v_ver.version = 1 then 'document.uploaded' else 'document.revised' end, 'document', v_doc.id::text,
    jsonb_build_object('module', 'documents', 'result', 'success', 'title', v_doc.title, 'version', v_ver.version, 'file_name', v_ver.original_filename,
      'size', v_ver.file_size, 'attached_to', v_doc.related_entity_type || ' ' || v_doc.related_reference));
  return jsonb_build_object('document_id', v_doc.id, 'version', v_ver.version, 'status', 'AVAILABLE');
end;
$$;

create or replace function public.document_upload_abort(p_version_id uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid := private.require_permission('documents.upload');
begin
  update public.document_versions set status = 'FAILED'
  where id = p_version_id and company_id = v_company and uploaded_by = auth.uid() and status = 'PENDING_UPLOAD';
end;
$$;

-- Authorises a download and records it; the client then requests a short-lived signed URL.
create or replace function public.document_download(p_version_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid := private.require_permission('documents.read');
  v_ver     public.document_versions;
  v_doc     public.documents;
begin
  select * into v_ver from public.document_versions where id = p_version_id and company_id = v_company and status = 'AVAILABLE';
  if not found then
    raise exception 'Document not found.' using errcode = 'P0001';
  end if;
  select * into v_doc from public.documents where id = v_ver.document_id;
  if not private.document_readable(v_doc.company_id, v_doc.related_entity_type) then
    raise exception 'You are not allowed to open this document (requires %).', private.document_entity_permission(v_doc.related_entity_type) using errcode = '42501';
  end if;
  perform private.write_audit_log(v_company, 'document.downloaded', 'document', v_doc.id::text,
    jsonb_build_object('module', 'documents', 'result', 'success', 'title', v_doc.title, 'version', v_ver.version));
  return jsonb_build_object('bucket', 'documents', 'storage_path', v_ver.storage_path, 'file_name', v_ver.original_filename, 'mime_type', v_ver.mime_type,
    'expires_in', 60);
end;
$$;

create or replace function public.document_archive(p_document_id uuid, p_reason text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_company uuid := private.require_permission('documents.read');
  v_doc     public.documents;
begin
  select * into v_doc from public.documents where id = p_document_id and company_id = v_company for update;
  if not found or not private.document_readable(v_doc.company_id, v_doc.related_entity_type) then
    raise exception 'Document not found.' using errcode = 'P0001';
  end if;
  if not (private.has_permission(v_company, 'documents.manage') or (v_doc.created_by = auth.uid() and private.has_permission(v_company, 'documents.upload'))) then
    raise exception 'Only the uploader or a documents administrator can archive this document.' using errcode = '42501';
  end if;
  if v_doc.status = 'ARCHIVED' then
    raise exception 'The document is already archived.' using errcode = 'P0001';
  end if;
  if length(btrim(coalesce(p_reason, ''))) < 5 then
    raise exception 'Enter the reason for archiving (at least 5 characters).' using errcode = 'P0001';
  end if;
  update public.documents set status = 'ARCHIVED', archived_by = auth.uid(), archived_at = now(), archive_reason = left(btrim(p_reason), 500), updated_at = now()
  where id = v_doc.id;
  perform private.write_audit_log(v_company, 'document.archived', 'document', v_doc.id::text,
    jsonb_build_object('module', 'documents', 'result', 'success', 'title', v_doc.title, 'reason', left(btrim(p_reason), 300)));
  return jsonb_build_object('status', 'ARCHIVED');
end;
$$;

-- Records a user can attach documents to (search by reference).
create or replace function public.document_entity_search(p_entity_type text, p_term text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_company uuid := private.require_permission('documents.read');
  v_t       text := '%' || replace(replace(btrim(coalesce(p_term, '')), '%', ''), '_', '') || '%';
begin
  if private.document_entity_permission(p_entity_type) is null or not private.has_permission(v_company, private.document_entity_permission(p_entity_type)) then
    return '[]'::jsonb;
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', id, 'reference', reference)) from (
    select p.id, p.sku || ' — ' || p.product_name as reference from public.products p where p_entity_type = 'PRODUCT' and p.company_id = v_company and (p.sku ilike v_t or p.product_name ilike v_t)
    union all select b.id, coalesce(b.batch_number, 'Untracked lot') || ' · ' || p.sku from public.inventory_batches b join public.products p on p.id = b.product_id
      where p_entity_type = 'BATCH' and b.company_id = v_company and (b.batch_number ilike v_t or p.sku ilike v_t)
    union all select w.id, w.warehouse_code || ' — ' || w.warehouse_name from public.warehouses w where p_entity_type = 'WAREHOUSE' and w.company_id = v_company and (w.warehouse_code ilike v_t or w.warehouse_name ilike v_t)
    union all select o.id, o.production_order_number from public.production_orders o where p_entity_type = 'PRODUCTION_ORDER' and o.company_id = v_company and o.production_order_number ilike v_t
    union all select o.id, o.outsourcing_order_number || ' · ' || o.supplier_name from public.outsourcing_orders o where p_entity_type = 'OUTSOURCING_ORDER' and o.company_id = v_company and (o.outsourcing_order_number ilike v_t or o.supplier_name ilike v_t)
    union all select o.id, o.customer_po_number || ' (' || o.po_reference || ')' from public.customer_purchase_orders o where p_entity_type = 'CUSTOMER_PO' and o.company_id = v_company and o.is_current and (o.customer_po_number ilike v_t or o.po_reference ilike v_t)
    union all select s.id, s.sales_order_number || ' · ' || s.customer_name_snapshot from public.sales_orders s where p_entity_type = 'SALES_ORDER' and s.company_id = v_company and (s.sales_order_number ilike v_t or s.customer_name_snapshot ilike v_t)
    union all select f.id, f.fulfilment_number from public.fulfilments f where p_entity_type = 'DISPATCH' and f.company_id = v_company and f.fulfilment_number ilike v_t
    union all select i.id, coalesce(i.invoice_number, 'Draft') || ' · ' || i.customer_legal_name from public.sales_invoices i where p_entity_type = 'INVOICE' and i.company_id = v_company and i.status <> 'DISCARDED' and (i.invoice_number ilike v_t or i.customer_legal_name ilike v_t)
    union all select n.id, coalesce(n.note_number, 'Draft note') from public.invoice_adjustment_notes n where p_entity_type = 'ADJUSTMENT_NOTE' and n.company_id = v_company and n.status <> 'DISCARDED' and coalesce(n.note_number, '') ilike v_t
    union all select c.id, c.customer_code || ' — ' || c.customer_name from public.customers c where p_entity_type = 'CUSTOMER' and c.company_id = v_company and (c.customer_code ilike v_t or c.customer_name ilike v_t)
    union all select c.id, c.legal_name from public.companies c where p_entity_type = 'COMPANY' and c.id = v_company
    limit 20) x), '[]'::jsonb);
end;
$$;

create or replace view public.document_list
with (security_invoker = true) as
select d.*, v.id as current_version_id, v.original_filename, v.file_size, v.mime_type, v.extension, v.uploaded_at, v.uploaded_by,
  (select count(*) from public.document_versions vv where vv.document_id = d.id and vv.status = 'AVAILABLE') as version_count
from public.documents d
left join public.document_versions v on v.document_id = d.id and v.version = d.current_version and v.status = 'AVAILABLE';

revoke all on public.document_list from anon, authenticated;
grant select on public.document_list to authenticated;

revoke all on function public.document_upload_rules() from public, anon;
revoke all on function public.document_upload_prepare(text, uuid, text, text, text, bigint, text, text, uuid, text) from public, anon;
revoke all on function public.document_upload_complete(uuid, text) from public, anon;
revoke all on function public.document_upload_abort(uuid) from public, anon;
revoke all on function public.document_download(uuid) from public, anon;
revoke all on function public.document_archive(uuid, text) from public, anon;
revoke all on function public.document_entity_search(text, text) from public, anon;
grant execute on function public.document_upload_rules(), public.document_upload_prepare(text, uuid, text, text, text, bigint, text, text, uuid, text),
  public.document_upload_complete(uuid, text), public.document_upload_abort(uuid), public.document_download(uuid), public.document_archive(uuid, text),
  public.document_entity_search(text, text) to authenticated;
